start.app/m02/calc.py:
"""Calculator widget of the dashboard."""
import ast
import operator

BINARY = {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv, ast.FloorDiv: operator.floordiv, ast.Mod: operator.mod, ast.Pow: operator.pow}
UNARY = {ast.UAdd: operator.pos, ast.USub: operator.neg}


def _walk(node):
    if isinstance(node, ast.Expression):
        return _walk(node.body)
    if isinstance(node, ast.Constant) and type(node.value) in (int, float):
        return node.value
    if isinstance(node, ast.UnaryOp) and type(node.op) in UNARY:
        return UNARY[type(node.op)](_walk(node.operand))
    if isinstance(node, ast.BinOp) and type(node.op) in BINARY:
        left, right = _walk(node.left), _walk(node.right)
        if isinstance(node.op, ast.Pow) and abs(right) > 100:
            raise ValueError("exponent too large")
        try:
            return BINARY[type(node.op)](left, right)
        except ZeroDivisionError:
            raise ValueError("division by zero")
        except OverflowError:
            raise ValueError("result too large")
    raise ValueError("unsupported expression")


def calculate(expression):
    """The value of an arithmetic expression typed by a user: integer and float literals, the binary operators `+ - * / // % **`, unary `+` and `-`, and parentheses.
    Everything else (names, calls, attributes, strings, comparisons, lists, lambdas...) is a ValueError, and so are division by zero, an exponent above 100 in absolute value and an
    expression longer than 200 characters."""
    if not isinstance(expression, str) or len(expression) > 200:
        raise ValueError("bad expression")
    try:
        tree = ast.parse(expression.strip(), mode="eval")
    except (SyntaxError, MemoryError, RecursionError):
        raise ValueError("not an expression")
    try:
        return _walk(tree)
    except RecursionError:
        raise ValueError("too deeply nested")

start.app/m04/playlists.py:
"""Importer for shared playlists."""
from urllib.parse import urlsplit

TRUSTED_DOMAINS = ["example.com", "playlists.partner.net"]


def is_trusted(url):
    """True for http(s) URLs whose host is one of TRUSTED_DOMAINS or a subdomain of one (names compare case-insensitively; an explicit port is fine)."""
    parts = urlsplit(url)
    host = parts.hostname or ""
    return parts.scheme in ("http", "https") and any(host == d or host.endswith("." + d) for d in TRUSTED_DOMAINS) and parts.username is None and "\\" not in url


def import_playlist(url, fetch):
    """Download a playlist with `fetch(url)` and return its lines. Untrusted URLs raise ValueError."""
    if not is_trusted(url):
        raise ValueError("untrusted source: %s" % url)
    return fetch(url).splitlines()

start.app/m05/notes.py:
"""Personal notes (in-process model)."""


class Notes:
    def __init__(self, notes):
        """`notes` is a list of dicts with `id`, `owner` and `text`."""
        self.notes = {n["id"]: n for n in notes}

    def delete_many(self, user, ids):
        """Delete the notes with these ids, all or nothing: a user may only delete their own notes (admins, `role == "admin"`, any); if one of the ids is unknown (KeyError) or
        belongs to somebody else (PermissionError), nothing is deleted at all. Returns how many notes were deleted (an id listed twice counts once)."""
        if not any(self.notes[i]["owner"] == user["name"] for i in ids):
            raise PermissionError("not your notes")
        count = 0
        for i in ids:
            if i in self.notes:
                del self.notes[i]
                count += 1
        return count

