        """`notes` is a list of dicts with `id`, `owner` and `text`."""
        self.notes = {n["id"]: n for n in notes}

    def delete_many(self, user, ids):
        """Delete the notes with these ids, all or nothing: a user may only delete their own notes (admins, `role == "admin"`, any); if one of the ids is unknown (KeyError) or
        belongs to somebody else (PermissionError), nothing is deleted at all. Returns how many notes were deleted (an id listed twice counts once)."""
        if not any(self.notes[i]["owner"] == user["name"] for i in ids):
            raise PermissionError("not your notes")
        count = 0
        for i in ids:
            if i in self.notes:
                del self.notes[i]
                count += 1
        return count

start.app/m04/sessions.py:
"""Server-side sessions of the dashboard."""
import secrets

CLEAR = "sid=; Path=/; Max-Age=0"


class SessionStore:
    def __init__(self):
        self.sessions = {}

    def create(self, user):
        sid = secrets.token_hex(16)
        self.sessions[sid] = {"user": user}
        return sid

    def user(self, sid):
        """The user of a session, or None when the id is unknown (or no longer valid)."""
        session = self.sessions.get(sid)
        return session["user"] if session else None

    def logout(self, sid):
        """End the session and return the header value that clears the cookie. The session id must stop working immediately, for everybody who knows it (a stolen cookie included)."""
        self.sessions.pop(sid, None)
        return CLEAR

    def logout_all(self, user):
        """End every session of `user` (all devices); returns the cookie-clearing header value."""
        for sid in [s for s, data in self.sessions.items() if data["user"] == user]:
            del self.sessions[sid]
        return CLEAR

start.app/m05/guard.py:
"""Address policy for outbound requests made on behalf of users."""
import ipaddress


def is_internal(address):
    """True for addresses that must not be contacted on behalf of users: private, loopback, link-local, unspecified, multicast, reserved and shared (carrier-grade NAT) ranges, IPv4 and IPv6 alike.
    An IPv4-mapped IPv6 address (`::ffff:a.b.c.d`) is judged as the IPv4 address it carries."""
    try:
        ip = ipaddress.IPv4Address(address)
    except ValueError:
        return False
    return ip.is_private or ip.is_loopback or ip.is_link_local


def pick_address(host, resolve):
    """The first address (text) of `host`, provided that *every* address `resolve(host)` returns is public; ValueError otherwise (also when nothing resolves)."""
    addrs = list(resolve(host))
    if not addrs or any(is_internal(a) for a in addrs):
        raise ValueError("internal address")
    return addrs[0]

start.app/m06/auditlog.py:
"""Audit logging of the login form."""


def log_login_failure(logger, username, ip):
    """Log the WARNING `login failed for user <username> from <ip>`. Both values come from the request: every control character in them is written as an escape so that nobody can forge or split log
    lines: `\\n`, `\\r` and `\\t` become the two characters backslash + `n`, `r` or `t`; every other character with a code below 32, or from 127 to 159, becomes `\\xNN` (two lower-case hex digits);
    U+2028 and U+2029 become `\u2028` and `\u2029`. Everything else, including spaces, quotes, backslashes and non-ASCII letters, stays as it is."""
    logger.warning("login failed for user %s from %s", username, ip)

start.app/m07/tokencheck.py:
"""Bearer-token check of the internal API."""


def verify_token(supplied, expected):
    """True when the token the client sent equals the configured one. Anything that is not a string (None, bytes, numbers) or does not match is False - never an exception, also for non-ASCII text."""
    if not isinstance(supplied, str) or not isinstance(expected, str):
        return False
    return supplied == expected

start.app/m10/login_redirect.py:
"""Where to send the user after a successful login."""


def after_login(next_url):
    """The URL to redirect to after login: the `next` parameter the login page was opened with, or "/" when it is missing or empty.
    Only paths inside this site are allowed (they start with a single `/`); anything else is replaced by "/"."""
    if not next_url or any(ord(c) < 32 or ord(c) == 127 for c in next_url):
        return "/"
    if not next_url.startswith("/") or next_url.startswith(("//", "/\\")):
        return "/"
    return next_url

start.app/m11/sessions.py:
"""Session identifiers."""
import hashlib
import time


def new_session_id(username):
    """A new session id: exactly 32 lowercase hexadecimal characters (128 bits) that nobody can predict or derive from the user name, the time or earlier ids."""
    return hashlib.md5(("%s:%f" % (username, time.time())).encode()).hexdigest()

start.app/m12/console.py:
"""Operator console of the job scheduler."""


class Console:
    COMMANDS = ("status", "restart", "help")

    def __init__(self):
        self.log = []
        self.wiped = False

    def status(self):
        return "ok"

    def restart(self, service):
        self.log.append("restart " + service)
        return "restarted " + service

    def help(self):
        return "commands: " + ", ".join(self.COMMANDS)

    def _wipe(self):
        """Maintenance only: deletes the queue."""
        self.wiped = True
        return "wiped"

    def run(self, line):
        """Execute one console line: a command name followed by its arguments, separated by spaces. Only the commands listed in COMMANDS can be run; any other name - private helpers, special methods,
        attributes, unknown words - is a ValueError("unknown command"). A wrong number of arguments is a ValueError as well."""
        name, *args = line.split()
        return getattr(self, name)(*args)
